\documentclass[border=1mm]{standalone}
\usepackage{pgfplots}
\usepgfplotslibrary{patchplots}
\usepgfplotslibrary{colormaps}
\usepackage{tikz-3dplot}


\begin{document}

	\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

	\pagestyle{empty}

\begin{tikzpicture}[
	scale=1.5,
	declare function={f(\t)=0.5*sin(deg(\t))+1;}]

\begin{axis}[
		clip=false,
		view={115}{20},
		hide axis,
		xmin=-3,xmax=3,
		ymin=-3,ymax=3,
		zmin=-2.5,zmax=2.5,
	]

	% Axes
	\def\axwidth{0.6}
	% X
 	\draw[black, line width=\axwidth, -stealth] (axis cs:-3,0,0) -- (axis cs:3,0,0) 
 		node[left, xshift=4pt, yshift=-3pt] {\scriptsize $x$};	
	% Y
 	\draw[black, line width=\axwidth, -stealth] (axis cs:0,-3,0) -- (axis cs:0,3,0) 
 		node[right, xshift=0pt, yshift=0pt] {\scriptsize $y$};	
	% Z
	\draw[black, line width=\axwidth, -stealth] (axis cs:0,0,-2.5) -- (axis cs:0,0,2.5) 
		node[above] {\scriptsize $z$};


	% Rs
	\draw[orangepeel, line width=\axwidth, dashed] 
		(axis cs:\xx,0,0) -- (axis cs:{\xx},{f(\xx)*cos(0)},{f(\xx)*sin(0)});

	% Curves
	\draw[color=deepskyblue, line width=\axwidth*1.5, samples=400] plot[domain=-3:3, variable=\t] 
		(axis cs:{\t},{f(\t)},{0});
	\node[deepskyblue!80!black] at (axis cs:2,2.5,0){\footnotesize $y=f(x)$};
	\node[circle, draw=none, fill=black, inner sep=0.75pt, 
		label={[below=1pt]: \tiny $\color{fadedpink!80!black}x$}] at 
			(axis cs:\xx,0,0) {};

	% Rot
	\def\xx{2}
	\draw[color=orangepeel, line width=\axwidth, samples=400] plot[domain=0:360, variable=\t] 
		(axis cs:{\xx},{f(\xx)*cos(\t)},{f(\xx)*sin(\t)});

	\node[circle, draw=none, fill=deepskyblue, inner sep=0.75pt] at 
		(axis cs:{\xx},{f(\xx)*cos(0)},{f(\xx)*sin(0)}) {};

	\node[above=2pt, xshift=-25pt] at (axis cs:{\xx},{f(\xx)*cos(100)},{f(\xx)*sin(100)}) {\scriptsize 
		$({\color{fadedpink!80!black}x}, {\color{orangepeel!80!black} \textrm{circle}_1, \textrm{circle}_2})$};


\end{axis}
\end{tikzpicture}
\end{document}

